from typing import Dict, Mapping


def abc_classify(values: Mapping[str, int], a_pct: int = 80, b_pct: int = 95) -> Dict[str, str]:
    """
    ABC classification of SKUs by value share.
    """
    if not (0 < a_pct <= b_pct <= 100):
        raise ValueError("Invalid thresholds")

    total = 0
    for v in values.values():
        if v < 0: raise ValueError("Negative value")
        total += v

    res: Dict[str, str] = {}
    if total == 0:
        return {sku: "C" for sku in values}

    sorted_items = sorted(values.items(), key=lambda x: (-x[1], x[0]))
    cum = 0
    for sku, val in sorted_items:
        if val == 0:
            res[sku] = "C"
            continue
        cum += val
        share = (cum * 100) / total
        if share <= a_pct + 1e-9:
            res[sku] = "A"
        elif share <= b_pct + 1e-9:
            res[sku] = "B"
        else:
            res[sku] = "C"

    # Fill in any missing 0-value SKUs if they weren't in sorted_items (though they should be)
    for sku in values:
        if sku not in res:
            res[sku] = "C"

    return res
