    if type_u in {"RCV", "SHP", "RTN"} and raw_qty <= 0:
        raise ValueError(f"{type_u} quantity must be positive")
    if type_u == "ADJ" and raw_qty == 0:
        raise ValueError("ADJ quantity cannot be zero")

    qty = raw_qty
